def _has_double_script(
        latex_string: str
        ) -> bool:
    """
    Return `True` if there is at least one double superscript
    or double subscript in `latex_string` 

    This function fails to give correct outputs for more
    nuanced texts, such as `r"x^{2}_{3}^{4}"`; while in
    principle, the function should return `True` on this
    input, the actual return value is `False`.

    This is a helper function of `math_mode_string_is_syntactically_valid`
    """
    # Remove all whitespace from the string
    latex_string = ''.join(latex_string.split())
    
    # Function to match balanced braces
    def match_braces(s, start):
        count = 0
        for i, char in enumerate(s[start:], start):
            if char == '{':
                count += 1
            elif char == '}':
                count -= 1
                if count == 0:
                    return i
        return len(s) - 1

    # Find all subscripts and superscripts
    i = 0
    last_script = None
    while i < len(latex_string):
        if latex_string[i] in '^_' and (i == 0 or latex_string[i-1] != '\\'):
            current_script = latex_string[i]
            i += 1
            if i < len(latex_string):
                if latex_string[i] == '{':
                    end = match_braces(latex_string, i)
                    script_content = latex_string[i:end+1]
                    i = end + 1
                else:
                    script_content = latex_string[i]
                    i += 1
                
                if last_script and last_script[0] == current_script:
                    return True
                last_script = (current_script, script_content)
        else:
            if latex_string[i] not in '^_':
                last_script = None
            i += 1

    return False

# %% ../../../nbs/01_helper_20.latex.core.ipynb #3e1f8794
def _has_double_script_literal(
        latex_string: str
        ) -> bool:
    """
    Return `True` if there is at least one double superscript
    or double subscript in `latex_string` by virtue of having
    `__`, `_^`, `^_, `^^`

    This is a helper function of `math_mode_string_is_syntactically_valid`
    """
    for bad_text in ['__', '_^', '^_', '^^']:
        if bad_text in latex_string:
            return True
    return False

# %% ../../../nbs/01_helper_20.latex.core.ipynb #954f5c04
def _has_unescaped_dollar(s):
    # Pattern explanation:
    # (?<!\\) is a negative lookbehind assertion that ensures the dollar sign is not preceded by a backslash
    # \$ matches a literal dollar sign
    pattern = r'(?<!\\)(\\\\)*\$'
    match = re.search(pattern, s)
    return bool(match)

# %% ../../../nbs/01_helper_20.latex.core.ipynb #52801c07
def get_dollar_sign_syntax_errors(
    text: str,
    check_spacing: bool = False
) -> list[str]:
    """
    Identifies structural and balance errors involving $ and $$ delimiters.
    """
    errors = []
    dollar_groups = []

    # 1. Find all unescaped dollar sequences
    i = 0
    while i < len(text):
        if text[i] == '$':
            start_idx = i
            while i < len(text) and text[i] == '$':
                i += 1
            length = i - start_idx
            bs_count = 0
            check_idx = start_idx - 1
            while check_idx >= 0 and text[check_idx] == '\\':
                bs_count += 1
                check_idx -= 1
            if bs_count % 2 == 0:
                dollar_groups.append((start_idx, length))
            else:
                # NEW CHECK: If it's escaped ($), is it likely a typo?
                # Flag escaped dollars that are followed by punctuation or spaces
                # as they are rarely intended as literals in math notes.
                if i < len(text) and text[i] in '. ,;)]':
                    errors.append(f"Suspicious escaped dollar sign '\\$' at index {start_idx-1}.")
            continue
            # if bs_count % 2 == 0:
            #     dollar_groups.append((start_idx, length))
            # continue
        i += 1

    num_double = 0
    num_single = 0
    for idx, length in dollar_groups:
        if length == 1: num_single += 1
        elif length == 2: num_double += 1
        else:
            if length % 2 != 0:
                errors.append(f"Invalid dollar sequence of length {length} at index {idx}.")
                num_double += length // 2
                num_single += 1
            else:
                num_double += length // 2

    if num_double % 2 != 0:
        errors.append(f"Unbalanced display math ($$): {num_double} found.")
    if num_single % 2 != 0:
        errors.append(f"Unbalanced inline math ($): {num_single} found.")

    # 4. Newline check for inline math
    singles = [dg for dg in dollar_groups if dg[1] == 1]
    for j in range(0, len(singles) // 2 * 2, 2):
        s_idx, _ = singles[j]
        e_idx, _ = singles[j + 1]
        if '\n' in text[s_idx + 1:e_idx]:
            errors.append(f"Inline math ($) starting at index {s_idx} spans a newline.")

    # 5. Spacing check logic
    if check_spacing:
        doubles = [dg for dg in dollar_groups if dg[1] == 2]
        for pairs, delim in ((singles, "$"), (doubles, "$$")):
            dlen = len(delim)
            for j in range(0, len(pairs) // 2 * 2, 2):
                s_idx, _ = pairs[j]
                e_idx, _ = pairs[j + 1]
                
                # Check character immediately AFTER opener
                if s_idx + dlen < len(text) and text[s_idx + dlen].isspace():
                    errors.append(f"Opening {delim} at {s_idx} is followed by whitespace.")
                
                # Check character immediately BEFORE closer
                # We ensure e_idx > s_idx + dlen so we aren't looking at the opener itself
                if e_idx > s_idx + dlen and text[e_idx - 1].isspace():
                    errors.append(f"Closing {delim} at {e_idx} is preceded by whitespace.")

    return errors

# %% ../../../nbs/01_helper_20.latex.core.ipynb #36f4507d
def detect_unbalanced_environments(
        latex_string: str) -> list[str]:
    # Define a regex pattern to match \begin{...} and \end{...}
    pattern = r'\\(begin|end)\{([^}]+)\}'
    
    # Stack to keep track of opened environments
    stack = []
    # List to store errors
    errors = []

    # Find all matches in the LaTeX string
    for match in re.finditer(pattern, latex_string):
        command, env_name = match.groups()
        
        if command == 'begin':
            # Push the environment name onto the stack
            stack.append(env_name)
        elif command == 'end':
            # Check if there is a matching begin for this end
            if stack and stack[-1] == env_name:
                stack.pop()  # Match found, pop from stack
            else:
                # Mismatch found, record the error
                errors.append(f"Mismatched \\end{{{env_name}}} at position {match.start()}")

    # If there are any unmatched begin commands left in the stack, report them
    while stack:
        unmatched_env = stack.pop()
        errors.append(f"Unmatched \\begin{{{unmatched_env}}}")

    return errors

# %% ../../../nbs/01_helper_20.latex.core.ipynb #ec52d14f
def latex_math_mode_has_soft_syntax_oddities(text: str) -> bool:
    """
    Determines if a predicted notation string needs syntax correction.
    
    Returns True if:
    1. LaTeX syntax is invalid (e.g. unbalanced curly braces).
    2. 'Soft' syntax is invalid (unbalanced parentheses or brackets).
    """
    if not text:
        return False

    # 1. Check strict LaTeX validity (Curly braces)
    # You can use your existing `math_mode_string_is_syntactically_valid` here if you have it.
    # Otherwise, a simple counter works for the basics:
    if text.count('{') != text.count('}'):
        return True
        
    # 2. Check "Soft" validity (Parentheses and Brackets)
    # This addresses your specific concern about unbalanced parens.
    stack = []
    pairs = {')': '(', ']': '['}
    
    for char in text:
        if char in '([':
            stack.append(char)
        elif char in ')]':
            if not stack or stack[-1] != pairs[char]:
                return True # Unmatched closer
            stack.pop()
            
    if stack:
        return True # Unmatched opener
        
    return False

